select jsonb_build_object('ai_rows',(select jsonb_agg(to_jsonb(a) order by analysis_date) from public.ai_region_analysis a),'counts',jsonb_build_object('raw',(select count(*) from public.raw_api_data),'trend',(select count(*) from public.naver_trend),'tourism',(select count(*) from public.tourism_demand),'places',(select count(*) from public.local_places),'archive',(select count(*) from public.tourism_demand_metric_archive)),'seoul',(select to_jsonb(t) from public.tourism_demand t where region_code='11' order by reference_date desc limit 1)) as ai_verification;
